#include <stdio.h>
#include "sheen/broadcast.h"
int main(int argc,char **argv){if(argc!=2){fprintf(stderr,"usage: %s MPEG_TS_FILE\\n",argv[0]);return 2;}sheen_broadcast_source s={.type=SHEEN_BROADCAST_NETWORK,.delivery=SHEEN_TUNER_DVBT};sheen_broadcast_multiplex m;int rc=sheen_broadcast_from_ts(argv[1],&s,&m);if(rc){fprintf(stderr,"broadcast parse failed: %d\\n",rc);return 1;}printf("{\"type\":\"%s\",\"program_count\":%zu,\"programs\":[",sheen_broadcast_type_name(m.source.type),m.program_count);for(size_t i=0;i<m.program_count;i++){if(i)putchar(',');printf("{\"service_id\":%u,\"program_number\":%u,\"pmt_pid\":%u,\"pcr_pid\":%u,\"stream_count\":%zu}",m.programs[i].service_id,m.programs[i].program_number,m.programs[i].pmt_pid,m.programs[i].pcr_pid,m.programs[i].stream_count);}printf("]}\n");return 0;}
